import datetimeimport logging_logger = logging.getLogger(__name__)def default(o):    """ Default JSON serializer.    """    if isinstance(o, (datetime.date, datetime.datetime)):        return o.isoformat()    if isinstance(o, bytes):        return str(o)    return Nonedef valid_response(data, status=200):    """Valid Response    This will be return when the http request was successfully processed."""    data = {"count": len(data) if type(data) not in [int, str, bool] else 1, "data": data, "status": status}    return datadef invalid_response(typ, message=None, status=401):    """Invalid Response    This will be the return value whenever the server runs into an error    either from the client or the server."""    response = {"type": typ, "message": str(message) if str(message) else "wrong arguments (missing validation)",                'status': status}    return response